mapper.delete:
DELETE FROM community_post_like
WHERE post_id = #{postId}
  AND member_id = #{memberId}

mapper.update:
UPDATE community_post
SET like_count = (SELECT COUNT(*) FROM community_post_like WHERE post_id = #{postId})
WHERE id = #{postId}

mapper.select:
SELECT like_count
FROM community_post
WHERE id = #{postId}
